center;justify-content:center;font-weight:900;border-radius:12px;transition:background .12s}.zo-game-root--jelly-block-garden .eyes{font-size:14px;letter-spacing:5px;line-height:1;color:#152035}.zo-game-root--jelly-block-garden .tray{display:flex;justify-content:center;gap:10px;margin-top:14px}.zo-game-root--jelly-block-garden .piece{display:grid;grid-template-columns:repeat(3,16px);grid-template-rows:repeat(3,16px);gap:3px;padding:10px}.zo-game-root--jelly-block-garden .piece[aria-pressed=true]{outline:3px solid var(--accent);outline-offset:2px}.zo-game-root--jelly-block-garden .pixel{border-radius:3px}.zo-game-root--jelly-block-garden .filled{background:var(--accent);box-shadow:inset 0 -4px #0002}.zo-game-root--jelly-block-garden .ghost{background:#95f0d5}.zo-game-root--jelly-block-garden .bad{background:#ec8d99}@media(max-width:420px){.zo-game-root--jelly-block-garden{padding:14px}.zo-game-root--jelly-block-garden .board{gap:4px}.zo-game-root--jelly-block-garden button{padding:10px 12px}.zo-game-root--jelly-block-garden .piece{padding:8px}}

